UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT ''All'' AS "label", ''All'' AS "value" union all (select DISTINCT vcrulename as "label", vcrulename as "value" FROM ui.rules where itenantid = :tenantid and bactive=true  ORDER BY label)'::text WHERE
idashboardqueryid = 36;

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vcclassname as "Class Name", r.iclassid as "Class ID",  d.vcdecisionname as "Decision Name", p.vcproductname as "Product Name", c.vcchannelname as "Channel Name", makeruser.vcusername as "Maker User", r.dtentrystamp at time zone ''asia/kolkata'' as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp at time zone ''asia/kolkata'' as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", r.bpayeemandatory as "Payee Mandatory", r.bpayermandatory  as "Payer Mandatory", cast(r.vcdecisionparams as text)   as "Decision Parameters", r.skipprocessing   as "Skip Processing", cast(r.attribs as text) as "Attribs" FROM ui.transactionclassesaudit r left join ui.decisions d on r.idecisionid = d.idecisionid left join masters.products p on r.iproductid = p.iproductid left join masters.channels c on r.ichannelid = c.ichannelid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp as date) between cast(:StartDate as date) and cast(:EndDate as date)-1;'::text WHERE
idashboardqueryid = 83;

UPDATE ui.dashboardresultset SET
vcdashboardresultsetschema = '{
    "Class Name":"string",
    "Class ID":"integer",
    "Decision Name":"string",
    "Product Name": "string",
    "Channel Name":"string",
    "Maker User":"string",
    "Maker Time Stamp":"datetime",
    "Maker & Checker Remarks":"string",
    "Checker User":"string",
    "Checker Time Stamp": "datetime",
    "Action": "string",
    "Payee Mandatory":"boolean",
    "Payer Mandatory":"boolean",
    "Decision Parameters":"string",
    "Attribs":"string",
    "Skip Processing":"integer"
}
'::text WHERE
idashboardresultsetid = 38;